UPDATE toolbox_job
SET status = 'PENDING',
    progress = 5,
    message = 'Task recovered after worker restart',
    started_at = NULL,
    updated_at = #{staleBefore}
WHERE organization_id = #{organizationId}
  AND status = 'PROCESSING'
  AND updated_at < #{staleBefore}

